    void coordinateSwitchDrain(SwitchMapObserver<?, ?> observer) {
        boolean cancelled = observer.cancelled;
        boolean done = observer.done;
        boolean delay = observer.delayErrors;
        Object source = observer.upstream;
        Object downstream = observer.downstream;
        alignSwitchDrain0(source, downstream, cancelled, done, delay);
        alignSwitchDrain1(source, downstream, cancelled, done, delay);
        alignSwitchDrain2(source, downstream, cancelled, done, delay);
        alignSwitchDrain3(source, downstream, cancelled, done, delay);
        alignSwitchDrain4(source, downstream, cancelled, done, delay);
        alignSwitchDrain5(source, downstream, cancelled, done, delay);
        alignSwitchDrain6(source, downstream, cancelled, done, delay);
        alignSwitchDrain7(source, downstream, cancelled, done, delay);
        alignSwitchDrain8(source, downstream, cancelled, done, delay);
        alignSwitchDrain9(source, downstream, cancelled, done, delay);
        alignSwitchDrain10(source, downstream, cancelled, done, delay);
        alignSwitchDrain11(source, downstream, cancelled, done, delay);
